"use client";

import * as React from "react";
import { Check } from "lucide-react";

type DivProps = React.ComponentProps<"div">;

export type DockItemStatus = "running" | "error" | "done";
export type DockActionTone = "default" | "primary" | "ghost";

export type DockActivityAction = {
  label: React.ReactNode;
  onClick?: () => void;
  tone?: DockActionTone;
};

export type DockActivity = {
  title: React.ReactNode;
  detail?: React.ReactNode;
  /** 0..1 — shown as the card's progress bar; the percentage is prefixed to the detail line while below 1. */
  progress?: number;
  actions?: DockActivityAction[];
};

export type DockItem = {
  id: string;
  label: string;
  icon: React.ReactNode;
  href?: string;
  onSelect?: () => void;
  /** 0..1 — a ring around the tile; reaching 1 closes the ring and shows a check. */
  progress?: number;
  badge?: number;
  status?: DockItemStatus;
  /** When present the tile opens a live card above itself. */
  activity?: DockActivity;
};

export type LiveActivityDockProps = DivProps & {
  items: DockItem[];
  expandedId?: string | null;
  defaultExpandedId?: string | null;
  onExpandedChange?: (id: string | null) => void;
  position?: "bottom" | "top";
  reflection?: boolean;
  compact?: boolean;
  "aria-label"?: string;
};

const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";
const FOCUSABLE = 'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';
const CARD_WIDTH = 288;
const EDGE_MARGIN = 8;

const SIZE = {
  regular: { tile: 44, radius: 12, gap: "gap-2.5", pad: "p-2.5", tileClass: "size-11 rounded-xl", dockRadius: "rounded-[22px]", icon: "[&>svg]:size-5" },
  compact: { tile: 36, radius: 10, gap: "gap-2", pad: "p-2", tileClass: "size-9 rounded-[10px]", dockRadius: "rounded-[18px]", icon: "[&>svg]:size-4" },
} as const;

const ACTION = {
  default: "bg-muted text-foreground hover:bg-muted/70",
  primary: "bg-primary text-primary-foreground hover:opacity-90",
  ghost: "text-muted-foreground hover:bg-muted hover:text-foreground",
} as const;

function useReducedMotion() {
  const [reduced, setReduced] = React.useState(true);
  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  return reduced;
}

function animatable(node: Element | null, reduced: boolean): node is HTMLElement {
  return !!node && !reduced && typeof (node as HTMLElement).animate === "function";
}

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));

/** Rounded-square outline that starts at the top centre and runs clockwise, so the ring fills like a clock. */
function ringPath(size: number, radius: number) {
  const inset = 1;
  const far = size - inset;
  const r = Math.max(1, radius);
  return [
    `M ${size / 2} ${inset}`,
    `H ${far - r}`, `A ${r} ${r} 0 0 1 ${far} ${inset + r}`,
    `V ${far - r}`, `A ${r} ${r} 0 0 1 ${far - r} ${far}`,
    `H ${inset + r}`, `A ${r} ${r} 0 0 1 ${inset} ${far - r}`,
    `V ${inset + r}`, `A ${r} ${r} 0 0 1 ${inset + r} ${inset}`,
    "Z",
  ].join(" ");
}

function ProgressRing({ progress, error, size, radius, reduced }: { progress: number; error: boolean; size: number; radius: number; reduced: boolean }) {
  const pathRef = React.useRef(null as SVGPathElement | null);
  const animation = React.useRef(null as Animation | null);
  const previous = React.useRef(clamp01(progress));
  const target = 1 - clamp01(progress);

  React.useLayoutEffect(() => {
    const path = pathRef.current;
    const from = 1 - previous.current;
    previous.current = clamp01(progress);
    if (!path || from === target) return;
    let current = from;
    const running = animation.current;
    if (running && running.playState === "running") {
      const computed = Number.parseFloat(getComputedStyle(path).strokeDashoffset);
      if (Number.isFinite(computed)) current = computed;
    }
    running?.cancel();
    path.style.strokeDashoffset = String(target);
    if (reduced || typeof path.animate !== "function") return;
    const delta = Math.abs(target - current);
    animation.current = path.animate(
      [{ strokeDashoffset: String(current) }, { strokeDashoffset: String(target) }],
      { duration: Math.min(900, Math.max(160, delta * 1400)), easing: delta < 0.1 ? "linear" : EASE },
    );
  }, [target, reduced]);

  React.useEffect(() => () => animation.current?.cancel(), []);

  return (
    <svg data-ring aria-hidden="true" viewBox={`0 0 ${size} ${size}`} width={size} height={size} className="pointer-events-none absolute -inset-0.5 overflow-visible">
      <path
        ref={pathRef}
        data-ring-path
        d={ringPath(size, radius)}
        pathLength={1}
        fill="none"
        stroke={error ? "var(--color-destructive)" : "var(--color-chart-2)"}
        strokeWidth={2}
        strokeLinecap="round"
        strokeDasharray="1 1"
        style={{ strokeDashoffset: target, transition: reduced ? "none" : "stroke 300ms" }}
      />
    </svg>
  );
}

function Roll({ value, reduced, className = "", id, as: Tag = "span" }: { value: React.ReactNode; reduced: boolean; className?: string; id?: string; as?: "span" | "p" }) {
  const key = typeof value === "string" || typeof value === "number" ? String(value) : null;
  const [state, setState] = React.useState({ key, shown: value, leaving: null as React.ReactNode, up: true });
  const inRef = React.useRef(null as HTMLSpanElement | null);
  const outRef = React.useRef(null as HTMLSpanElement | null);
  const timer = React.useRef(0);

  React.useLayoutEffect(() => {
    if (key === state.key) return;
    const previousKey = state.key;
    const up = key !== null && previousKey !== null && !Number.isNaN(Number(key)) && !Number.isNaN(Number(previousKey)) ? Number(key) >= Number(previousKey) : true;
    if (reduced || key === null || previousKey === null) { setState({ key, shown: value, leaving: null, up }); return; }
    setState({ key, shown: value, leaving: state.shown, up });
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setState((current) => ({ ...current, leaving: null })), 420);
  }, [key]);

  React.useLayoutEffect(() => {
    if (state.leaving === null) return;
    const sign = state.up ? 1 : -1;
    if (animatable(inRef.current, reduced)) inRef.current.animate([{ transform: `translateY(${sign * 100}%)`, opacity: 0 }, { transform: "translateY(0)", opacity: 1 }], { duration: 380, easing: EASE });
    if (animatable(outRef.current, reduced)) outRef.current.animate([{ transform: "translateY(0)", opacity: 1 }, { transform: `translateY(${-sign * 100}%)`, opacity: 0 }], { duration: 380, easing: EASE, fill: "forwards" });
  }, [state.leaving, state.key]);

  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  return (
    <Tag id={id} data-roll className={`relative grid overflow-hidden ${className}`}>
      <span ref={inRef} data-roll-item className="col-start-1 row-start-1 truncate">{state.shown}</span>
      {state.leaving !== null && <span ref={outRef} data-roll-item aria-hidden="true" className="col-start-1 row-start-1 truncate">{state.leaving}</span>}
    </Tag>
  );
}

type TileProps = {
  item: DockItem;
  compact: boolean;
  focused: boolean;
  expanded: boolean;
  dimmed: boolean;
  hideIcon: boolean;
  tooltipAllowed: boolean;
  cardId: string;
  reduced: boolean;
  registerRef: (node: HTMLElement | null) => void;
  onFocusItem: () => void;
  onActivate: () => void;
};

function Tile({ item, compact, focused, expanded, dimmed, hideIcon, tooltipAllowed, cardId, reduced, registerRef, onFocusItem, onActivate }: TileProps) {
  const size = compact ? SIZE.compact : SIZE.regular;
  const [hovered, setHovered] = React.useState(false);
  const nodeRef = React.useRef(null as HTMLElement | null);
  const previousStatus = React.useRef(item.status);
  const progress = item.progress === undefined ? undefined : clamp01(item.progress);
  const complete = item.status === "done" || (progress !== undefined && progress >= 1 && item.status !== "error");
  const wasComplete = React.useRef(complete);
  const hasActivity = !!item.activity;
  const glyph = item.status === "error" ? "error" : complete ? "done" : null;

  React.useLayoutEffect(() => {
    const node = nodeRef.current;
    const was = previousStatus.current;
    previousStatus.current = item.status;
    if (item.status === "error" && was !== "error" && animatable(node, reduced)) {
      node.animate(
        [{ transform: "translateX(0)" }, { transform: "translateX(-3px)" }, { transform: "translateX(3px)" }, { transform: "translateX(-2px)" }, { transform: "translateX(2px)" }, { transform: "translateX(0)" }],
        { duration: 380, easing: "ease-out" },
      );
    }
  }, [item.status, reduced]);

  React.useLayoutEffect(() => {
    const node = nodeRef.current;
    const was = wasComplete.current;
    wasComplete.current = complete;
    if (complete && !was && animatable(node, reduced)) {
      node.animate([{ transform: "scale(1)" }, { transform: "scale(1.04)", offset: 0.4 }, { transform: "scale(1)" }], { duration: 320, easing: EASE });
    }
  }, [complete, reduced]);

  const previousBadge = React.useRef(item.badge);
  React.useLayoutEffect(() => {
    const node = nodeRef.current;
    const was = previousBadge.current;
    previousBadge.current = item.badge;
    if (was !== undefined && item.badge !== undefined && was !== item.badge && animatable(node, reduced)) {
      node.animate([{ transform: "scale(1)" }, { transform: "scale(1.03)", offset: 0.3 }, { transform: "scale(1)" }], { duration: 260, easing: EASE });
    }
  }, [item.badge, reduced]);

  const statusText = item.status === "error" ? "failed" : complete ? "complete" : item.status === "running" ? "running" : progress !== undefined ? `${Math.round(progress * 100)}%` : null;
  const ariaLabel = [item.label, item.badge !== undefined ? `${item.badge} new` : null, statusText].filter(Boolean).join(", ");
  const tooltip = statusText ? `${item.label} · ${statusText}` : item.label;
  const showTooltip = tooltipAllowed && !expanded && hovered;

  const shared = {
    ref: (node: HTMLElement | null) => { nodeRef.current = node; registerRef(node); },
    id: `${cardId}-tile-${item.id}`,
    "data-tile": "",
    "data-id": item.id,
    "data-expanded": expanded ? "true" : "false",
    "data-dimmed": dimmed ? "true" : "false",
    "data-status": item.status,
    "data-progress": progress === undefined ? undefined : progress.toFixed(3),
    "data-complete": complete ? "true" : undefined,
    "aria-label": ariaLabel,
    tabIndex: focused ? 0 : -1,
    onFocus: onFocusItem,
    onPointerEnter: () => setHovered(true),
    onPointerLeave: () => setHovered(false),
    onBlur: () => setHovered(false),
    className: `group relative flex shrink-0 items-center justify-center bg-card text-foreground/80 shadow-sm dark:bg-muted/70 shadow-foreground/5 ring-1 ring-border/70 outline-none transition-[opacity,box-shadow] duration-300 motion-reduce:transition-none inset-shadow-[0_1px_0_color-mix(in_oklch,var(--color-foreground)_6%,transparent)] dark:inset-shadow-[0_1px_0_color-mix(in_oklch,var(--color-foreground)_14%,transparent)] hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring data-[dimmed=true]:opacity-60 data-[expanded=true]:ring-foreground/25 ${size.tileClass}`,
  };

  const content = (
    <>
      <span data-tile-icon className={`relative flex items-center justify-center transition-opacity duration-150 motion-reduce:transition-none ${size.icon} ${hideIcon ? "opacity-0" : "opacity-100"}`}>
        {item.icon}
      </span>
      {progress !== undefined && <ProgressRing progress={progress} error={item.status === "error"} size={size.tile + 4} radius={size.radius + 2} reduced={reduced} />}
      {item.badge !== undefined && (
        <span data-badge aria-hidden="true" className="absolute -right-1.5 -top-1.5 flex h-[18px] min-w-[18px] items-center justify-center rounded-full bg-primary px-1 font-mono text-[10px] font-medium tabular-nums leading-none text-primary-foreground ring-2 ring-background">
          <Roll value={item.badge} reduced={reduced} className="h-[12px] leading-[12px]" />
        </span>
      )}
      {glyph && (
        <span
          data-glyph={glyph}
          aria-hidden="true"
          className={`absolute flex size-4 items-center justify-center rounded-full text-background ring-2 ring-background ${item.badge !== undefined ? "-bottom-1.5 -right-1.5" : "-right-1.5 -top-1.5"} ${glyph === "done" ? "bg-chart-2" : "bg-destructive"}`}
        >
          {glyph === "done" ? <Check className="size-2.5" strokeWidth={3} aria-hidden="true" /> : <span className="text-[9px] font-bold leading-none">!</span>}
        </span>
      )}
      {item.status === "running" && <span data-running-dot aria-hidden="true" className="absolute -bottom-[7px] left-1/2 size-1 -translate-x-1/2 rounded-full bg-chart-2 animate-pulse motion-reduce:animate-none" />}
      <span
        data-tooltip
        aria-hidden="true"
        data-shown={showTooltip ? "true" : "false"}
        className={`pointer-events-none absolute bottom-full left-1/2 mb-2.5 -translate-x-1/2 whitespace-nowrap rounded-md bg-foreground px-2 py-1 text-[11px] font-medium leading-none text-background shadow-sm transition-opacity duration-150 motion-reduce:transition-none ${showTooltip ? "opacity-100" : "opacity-0 group-focus-visible:opacity-100"}`}
      >
        {tooltip}
      </span>
    </>
  );

  if (!hasActivity && item.href) {
    return (
      <a {...shared} href={item.href} onClick={() => item.onSelect?.()}>
        {content}
      </a>
    );
  }
  return (
    <button
      {...shared}
      type="button"
      aria-haspopup={hasActivity ? "dialog" : undefined}
      aria-expanded={hasActivity ? expanded : undefined}
      aria-controls={hasActivity && expanded ? cardId : undefined}
      onClick={onActivate}
    >
      {content}
    </button>
  );
}

export function LiveActivityDock({
  items,
  expandedId,
  defaultExpandedId = null,
  onExpandedChange,
  position = "bottom",
  reflection = true,
  compact = false,
  "aria-label": ariaLabel = "Dock",
  className = "",
  ref,
  ...rest
}: LiveActivityDockProps) {
  const reduced = useReducedMotion();
  const baseId = React.useId();
  const cardId = `${baseId}-card`;
  const size = compact ? SIZE.compact : SIZE.regular;
  const [localExpanded, setLocalExpanded] = React.useState(defaultExpandedId);
  const expanded = expandedId === undefined ? localExpanded : expandedId;
  const expandedItem = expanded ? items.find((item) => item.id === expanded && item.activity) ?? null : null;
  const active = expandedItem?.id ?? null;
  const [shown, setShown] = React.useState(active);
  const [flight, setFlight] = React.useState(null as null | { id: string; dir: "open" | "close" });
  const [focusId, setFocusId] = React.useState(items[0]?.id ?? "");
  const [announcement, setAnnouncement] = React.useState("");
  const rootRef = React.useRef(null as HTMLDivElement | null);
  const shelfRef = React.useRef(null as HTMLDivElement | null);
  const cardRef = React.useRef(null as HTMLDivElement | null);
  const bodyRef = React.useRef(null as HTMLDivElement | null);
  const ghostRef = React.useRef(null as HTMLSpanElement | null);
  const tileRefs = React.useRef({} as { [id: string]: HTMLElement | null });
  const focusCardNext = React.useRef(false);
  const lastHeight = React.useRef(0);
  const seen = React.useRef({} as { [id: string]: { status?: DockItemStatus; complete: boolean } });
  const flightToken = React.useRef(0);

  const setExpanded = React.useCallback((next: string | null, options?: { focusCard?: boolean }) => {
    focusCardNext.current = !!options?.focusCard;
    if (expandedId === undefined) setLocalExpanded(next);
    onExpandedChange?.(next);
  }, [expandedId, onExpandedChange]);

  const shownItem = shown ? items.find((item) => item.id === shown) ?? null : null;
  const shownActivity = shownItem?.activity;

  React.useLayoutEffect(() => {
    if (active) {
      setShown(active);
      setFlight({ id: active, dir: "open" });
    } else if (shown) {
      setFlight({ id: shown, dir: "close" });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active]);

  const placeCard = React.useCallback((id: string) => {
    const card = cardRef.current;
    const shelf = shelfRef.current;
    const tile = tileRefs.current[id];
    if (!card || !shelf || !tile) return null;
    const tileRect = tile.getBoundingClientRect();
    const shelfRect = shelf.getBoundingClientRect();
    const width = Math.min(CARD_WIDTH, window.innerWidth - EDGE_MARGIN * 2);
    const centre = tileRect.left + tileRect.width / 2;
    const left = Math.min(Math.max(centre - width / 2, EDGE_MARGIN), window.innerWidth - EDGE_MARGIN - width);
    card.style.width = `${width}px`;
    card.style.left = `${left - shelfRect.left}px`;
    card.style.setProperty("--tail-left", `${centre - left - 7}px`);
    return { tileRect };
  }, []);

  React.useLayoutEffect(() => {
    if (!flight) return;
    const token = ++flightToken.current;
    const card = cardRef.current;
    const ghost = ghostRef.current;
    const tile = tileRefs.current[flight.id];
    const tileIconBox = tile?.querySelector("[data-tile-icon]");
    const slotBox = card?.querySelector("[data-card-icon-glyph]");
    const tileIcon = tileIconBox?.querySelector("svg") ?? tileIconBox;
    const slot = slotBox?.querySelector("svg") ?? slotBox;
    const finish = () => {
      if (token !== flightToken.current) return;
      setFlight(null);
      if (flight.dir === "close") setShown(null);
    };
    if (!card || !ghost || !tileIcon || !slot) { finish(); return; }
    for (const running of [...card.getAnimations(), ...ghost.getAnimations()]) running.cancel();
    placeCard(flight.id);
    if (flight.dir === "open" && focusCardNext.current) {
      focusCardNext.current = false;
      const first = card.querySelector(FOCUSABLE);
      (first instanceof HTMLElement ? first : card).focus({ preventScroll: true });
    }
    if (!animatable(card, reduced)) { finish(); return; }
    const shelfRect = shelfRef.current?.getBoundingClientRect();
    const from = tileIcon.getBoundingClientRect();
    const to = slot.getBoundingClientRect();
    if (!shelfRect || from.width === 0 || to.width === 0) { finish(); return; }
    const scale = to.width / from.width;
    const dx = to.left + to.width / 2 - (from.left + from.width / 2);
    const dy = to.top + to.height / 2 - (from.top + from.height / 2);
    ghost.style.left = `${from.left - shelfRect.left}px`;
    ghost.style.top = `${from.top - shelfRect.top}px`;
    ghost.style.width = `${from.width}px`;
    ghost.style.height = `${from.height}px`;
    const start = "translate(0px, 0px) scale(1)";
    const end = `translate(${dx}px, ${dy}px) scale(${scale})`;
    const upward = position === "bottom" ? 10 : -10;
    if (flight.dir === "open") {
      const move = ghost.animate([{ transform: start }, { transform: end }], { duration: 360, easing: EASE, fill: "forwards" });
      card.animate([{ opacity: 0, transform: `translateY(${upward}px) scale(0.96)` }, { opacity: 1, transform: "translateY(0) scale(1)" }], { duration: 320, easing: EASE });
      move.onfinish = finish;
    } else {
      const move = ghost.animate([{ transform: end }, { transform: start }], { duration: 300, easing: EASE, fill: "forwards" });
      card.animate([{ opacity: 1, transform: "translateY(0) scale(1)" }, { opacity: 0, transform: `translateY(${upward * 0.6}px) scale(0.97)` }], { duration: 240, easing: "ease-in", fill: "forwards" });
      move.onfinish = finish;
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [flight]);

  React.useEffect(() => {
    if (!shown) return;
    const update = () => { placeCard(shown); };
    window.addEventListener("resize", update);
    return () => window.removeEventListener("resize", update);
  }, [shown, placeCard]);

  const contentKey = shownActivity ? `${typeof shownActivity.title === "string" ? shownActivity.title : "node"}|${typeof shownActivity.detail === "string" ? shownActivity.detail : "node"}|${shownActivity.progress !== undefined && shownActivity.progress < 1 ? "bar" : "flat"}|${shownActivity.actions?.length ?? 0}` : "";
  React.useLayoutEffect(() => {
    const body = bodyRef.current;
    if (!body || !shown) { lastHeight.current = 0; return; }
    const height = body.getBoundingClientRect().height;
    const previous = lastHeight.current;
    lastHeight.current = height;
    if (!previous || Math.abs(previous - height) < 0.5 || !animatable(body, reduced)) return;
    body.animate([{ height: `${previous}px` }, { height: `${height}px` }], { duration: 280, easing: EASE });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [contentKey, shown]);

  React.useEffect(() => {
    if (!active) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      setExpanded(null);
      tileRefs.current[active]?.focus({ preventScroll: true });
    };
    const onPointer = (event: PointerEvent) => {
      const root = rootRef.current;
      if (root && event.target instanceof Node && !root.contains(event.target)) setExpanded(null);
    };
    document.addEventListener("keydown", onKey);
    document.addEventListener("pointerdown", onPointer);
    return () => { document.removeEventListener("keydown", onKey); document.removeEventListener("pointerdown", onPointer); };
  }, [active, setExpanded]);

  React.useEffect(() => {
    const messages: string[] = [];
    for (const item of items) {
      const complete = item.status === "done" || (item.progress !== undefined && item.progress >= 1 && item.status !== "error");
      const before = seen.current[item.id];
      if (before) {
        if (complete && !before.complete) messages.push(`${item.label} complete`);
        else if (item.status === "error" && before.status !== "error") messages.push(`${item.label} failed`);
        else if (item.status === "running" && before.status !== "running") messages.push(`${item.label} running`);
      }
      seen.current[item.id] = { status: item.status, complete };
    }
    if (messages.length) setAnnouncement(messages.join(". "));
  }, [items]);

  const onToolbarKeyDown = (event: React.KeyboardEvent) => {
    const current = Math.max(0, items.findIndex((item) => item.id === focusId));
    let next = -1;
    if (event.key === "ArrowRight") next = (current + 1) % items.length;
    else if (event.key === "ArrowLeft") next = (current - 1 + items.length) % items.length;
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = items.length - 1;
    if (next >= 0) {
      event.preventDefault();
      const target = items[next];
      if (target) { setFocusId(target.id); tileRefs.current[target.id]?.focus({ preventScroll: true }); }
      return;
    }
    const targetId = event.target instanceof HTMLElement ? event.target.dataset.id : undefined;
    if ((event.key === "Enter" || event.key === " ") && targetId) {
      const item = items.find((candidate) => candidate.id === targetId);
      if (item?.activity) {
        event.preventDefault();
        setExpanded(active === item.id ? null : item.id, { focusCard: active !== item.id });
      }
      return;
    }
    if (event.key === "Tab" && !event.shiftKey && active && targetId === active) {
      const first = cardRef.current?.querySelector(FOCUSABLE);
      if (first instanceof HTMLElement) { event.preventDefault(); first.focus({ preventScroll: true }); }
    }
  };

  const onCardKeyDown = (event: React.KeyboardEvent) => {
    if (event.key !== "Tab" || !cardRef.current) return;
    const focusables = [...cardRef.current.querySelectorAll(FOCUSABLE)].filter((node): node is HTMLElement => node instanceof HTMLElement);
    if (!focusables.length) return;
    const first = focusables[0]!;
    const last = focusables[focusables.length - 1]!;
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
  };

  const activate = (item: DockItem) => {
    if (item.activity) setExpanded(active === item.id ? null : item.id);
    else item.onSelect?.();
  };

  const progress = shownActivity?.progress === undefined ? undefined : clamp01(shownActivity.progress);
  const percent = progress === undefined ? null : Math.round(progress * 100);
  const detailLine = [percent !== null && progress !== undefined && progress < 1 ? `${percent}%` : null, shownActivity?.detail ?? null].filter((part) => part !== null && part !== "");
  const top = position === "top";

  const shelf = (ghost: boolean) => items.map((item) => (
    ghost ? (
      <span key={item.id} aria-hidden="true" className={`flex shrink-0 items-center justify-center bg-card text-foreground/60 ring-1 ring-border/70 dark:bg-muted/70 ${size.tileClass} ${size.icon}`}>{item.icon}</span>
    ) : (
      <Tile
        key={item.id}
        item={item}
        compact={compact}
        focused={item.id === focusId}
        expanded={active === item.id}
        dimmed={!!active && active !== item.id}
        hideIcon={flight?.id === item.id}
        tooltipAllowed={!active}
        cardId={cardId}
        reduced={reduced}
        registerRef={(node) => { tileRefs.current[item.id] = node; }}
        onFocusItem={() => setFocusId(item.id)}
        onActivate={() => activate(item)}
      />
    )
  ));

  return (
    <div
      {...rest}
      ref={(node) => { rootRef.current = node; if (typeof ref === "function") ref(node); else if (ref) (ref as { current: HTMLDivElement | null }).current = node; }}
      data-slot="live-activity-dock"
      data-position={position}
      data-expanded={active ?? ""}
      data-compact={compact ? "true" : "false"}
      className={`relative inline-flex flex-col items-center ${className}`}
    >
      <div ref={shelfRef} data-shelf className="relative">
        <div
          role="toolbar"
          aria-label={ariaLabel}
          aria-orientation="horizontal"
          data-dock
          onKeyDown={onToolbarKeyDown}
          className={`relative flex items-center bg-background/70 ring-1 ring-border/80 backdrop-blur-md dark:bg-card/70 inset-shadow-[0_1px_0_var(--color-border)] shadow-[0_18px_40px_-16px_color-mix(in_oklch,var(--color-foreground)_28%,transparent)] ${size.gap} ${size.pad} ${size.dockRadius}`}
        >
          {shelf(false)}
        </div>
        {shownItem && shownActivity && (
          <div
            ref={cardRef}
            id={cardId}
            role="dialog"
            aria-labelledby={`${cardId}-title`}
            aria-describedby={detailLine.length ? `${cardId}-detail` : undefined}
            tabIndex={-1}
            data-live-card
            data-id={shownItem.id}
            data-state={flight?.dir === "close" ? "closing" : flight?.dir === "open" ? "opening" : "open"}
            onKeyDown={onCardKeyDown}
            className={`absolute z-20 outline-none ${top ? "top-[calc(100%+12px)] origin-top" : "bottom-[calc(100%+12px)] origin-bottom"}`}
            style={{ width: CARD_WIDTH }}
          >
            <span aria-hidden="true" data-tail className={`pointer-events-none absolute h-2 w-3.5 overflow-hidden ${top ? "-top-2" : "-bottom-2"}`} style={{ left: "var(--tail-left, 50%)" }}>
              <span className={`absolute left-[2px] size-2.5 rotate-45 bg-card ring-1 ring-border ${top ? "top-[3px]" : "-top-[5px]"}`} />
            </span>
            <div ref={bodyRef} data-card-body className="relative overflow-hidden rounded-2xl bg-card text-card-foreground shadow-xl shadow-foreground/10 ring-1 ring-border">
              <div className="flex items-start gap-3 p-3">
                <span data-card-icon className="flex size-9 shrink-0 items-center justify-center rounded-xl bg-muted text-foreground">
                  <span data-card-icon-glyph className={`flex items-center justify-center transition-opacity duration-150 motion-reduce:transition-none [&>svg]:size-5 ${flight ? "opacity-0" : "opacity-100"}`}>
                    {shownItem.icon}
                  </span>
                </span>
                <div className="min-w-0 flex-1 pt-0.5">
                  <Roll as="p" id={`${cardId}-title`} value={shownActivity.title} reduced={reduced} className="text-sm font-medium leading-5" />
                  {detailLine.length > 0 && (
                    <p id={`${cardId}-detail`} data-card-detail className="mt-0.5 truncate text-xs leading-4 text-muted-foreground tabular-nums">
                      {detailLine.map((part, index) => <React.Fragment key={index}>{index > 0 && <span aria-hidden="true"> · </span>}{part}</React.Fragment>)}
                    </p>
                  )}
                  {progress !== undefined && progress < 1 && (
                    <div role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={percent ?? 0} aria-label={shownItem.label} data-card-bar className="mt-2 h-1 w-full overflow-hidden rounded-full bg-muted">
                      <span data-card-bar-fill className={`block h-full w-full origin-left rounded-full transition-[transform,background-color] duration-200 ease-linear motion-reduce:transition-none ${shownItem.status === "error" ? "bg-destructive" : "bg-chart-2"}`} style={{ transform: `scaleX(${progress})` }} />
                    </div>
                  )}
                  {shownActivity.actions && shownActivity.actions.length > 0 && (
                    <div data-card-actions className="mt-2.5 flex items-center justify-end gap-1.5">
                      {shownActivity.actions.map((action, index) => (
                        <button
                          key={index}
                          type="button"
                          data-action
                          data-tone={action.tone ?? "default"}
                          onClick={() => action.onClick?.()}
                          className={`inline-flex h-7 items-center rounded-lg px-2.5 text-xs font-medium outline-none transition-[background-color,color,opacity] duration-200 motion-reduce:transition-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card ${ACTION[action.tone ?? "default"]}`}
                        >
                          {action.label}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}
        {flight && shownItem && (
          <span ref={ghostRef} aria-hidden="true" data-flip-ghost className={`pointer-events-none absolute z-30 flex items-center justify-center text-foreground will-change-transform ${size.icon}`}>
            {shownItem.icon}
          </span>
        )}
      </div>
      {reflection && !top && (
        <div aria-hidden="true" data-reflection className="pointer-events-none mt-1 h-6 w-full overflow-hidden opacity-[0.18]" style={{ maskImage: "linear-gradient(to bottom, black, transparent)", WebkitMaskImage: "linear-gradient(to bottom, black, transparent)" }}>
          <div data-reflection-image className={`flex items-center bg-background/70 ring-1 ring-border/80 dark:bg-card/70 ${size.gap} ${size.pad} ${size.dockRadius}`} style={{ transform: "scaleY(-1)" }}>
            {shelf(true)}
          </div>
        </div>
      )}
      <p role="status" aria-live="polite" data-announce className="sr-only">{announcement}</p>
    </div>
  );
}

